dtsPropsFor.ProductCard:
id: number | string;
sku: string;
title: string;
slug: string;
url: string;
categoryPath: string[];
/** صيغة الملفّ، مثل «PDF» / «Word» — تُصيَّر شريحة ثابتة. */
format: string;
/** السعر بالهللات (وحدات صغرى صحيحة) لا بالريالات. */
priceMinor: number;
/** السعر قبل الخصم — يُصيَّر مشطوبًا مع onSale. */
regularMinor?: number;
discountPct?: number;
onSale: boolean;
/** التقييم يُصيَّر فقط مع ratingCount؛ نجمة بلا عدد ادّعاء بلا مصدر. */
ratingAvg?: number;
ratingCount?: number;
/** الغلاف. غيابه يُصيَّر صندوقًا فارغًا صريحًا لا صورة نائبة. */
image?: { url: string; alt: string; w: number; h: number };
/** شارة تحريرية بلونَيها — لا تُشتقّ من المنتج، تُمرَّر. */
badge?: { label: string; bg: string; fg: string };
/** رتبة في قائمة مرتّبة (الأكثر مبيعًا) — تُصيَّر رقمًا في الزاوية. */
rank?: number;
editable?: boolean;
/** زرّ التذييل «أضف للسلة» — رابط تصريحي؛ بدونه لا زرّ (لا زرّ بلا وجهة). */
cta?: { label: string; href: string };
/** بديل الزرّ: عقدة جاهزة (زرّ عميل حقيقي مثلًا) — تفوز على cta عند وجودها. */
ctaSlot?: ReactNode;
/**
 * أزرار الوسائط (المفضّلة · المقارنة) — عقدة جاهزة يملكها المستدعي، تُرسم في
 * الزاوية المقابلة للشارات. لا يرسم المكوّن أيّ زرّ من عنده: زرٌّ بلا فعل ادّعاء.
 */
actions?: ReactNode;

dtsPropsFor.ProductCollection:
/**
 * إعدادات المجموعة كاملة. ابدأ دائمًا من COLLECTION_DEFAULTS وانشره:
 * `{ ...COLLECTION_DEFAULTS, cols: 4 }`.
 */
settings: {
  heading: string;
  headingLevel: 'h2' | 'h3' | 'none';
  hSize: number;
  hWeight: 700 | 800 | 900;
  /** «التخطيط خاصّية لا ملفّ» — مكوّن واحد يغطّيها كلّها. */
  layout: 'grid' | 'carousel' | 'slider' | 'list' | 'bento';
  cols: number;
  gap: number;
  density: 'comfy' | 'mid' | 'tight';
  mobCols: number;
  radius: number;
  border: 'none' | 'thin' | 'solid';
  shadow: 'none' | 'soft' | 'lift';
  surface: 'plain' | 'soft' | 'warm' | 'dark';
  ratio: 'square' | 'wide' | 'tall';
  fit: 'cover' | 'contain';
  /** يعمل img وbadge وcta؛ أمّا title وprice فمطلوبان في البطاقة فلا يُحذفان. */
  parts: { img: boolean; title: boolean; price: boolean; badge: boolean; cta: boolean };
  hover: 'lift' | 'glow' | 'tilt' | 'none';
  spotlight: boolean;
  motion: number;
  entrance: 'up' | 'fade' | 'zoom' | 'none';
  hide: { desk: boolean; tab: boolean; mob: boolean };
  anchor: string;
  cls: string;
  emptyMsg: string;
  errorMsg: string;
};
/** نفس شكل ProductCardProps تمامًا. */
items: Array<{
  id: number | string; sku: string; title: string; slug: string; url: string;
  categoryPath: string[]; format: string; priceMinor: number; onSale: boolean;
  regularMinor?: number; discountPct?: number; ratingAvg?: number; ratingCount?: number;
/** الغلاف. غيابه يُصيَّر صندوقًا فارغًا صريحًا لا صورة نائبة. */
image?: { url: string; alt: string; w: number; h: number };
  /** شارة تحريرية بلونَيها — لا تُشتقّ من المنتج، تُمرَّر. */
badge?: { label: string; bg: string; fg: string };
  rank?: number; editable?: boolean;
  cta?: { label: string; href: string };
}>;
/** الحالات الأربع الإلزامية — تُمرَّر صراحةً لا تُستنتج من طول القائمة. */
state?: 'ready' | 'loading' | 'empty' | 'error';
/** يوقف حركة الدخول: تستعمله المعاينة لإعادة التشغيل عند الطلب. */
replayKey?: string | number;

dtsPropsFor.TrustStrip:
variant?: 'band' | 'classic' | 'minimal' | 'glass' | 'smart';
/** بقائمة فارغة يُصيَّر لا شيء — المكوّن لا يشحن نصًّا خاصًّا به. */
items: ReadonlyArray<{
  id: string;
  /** الادّعاء نفسه، مثل «دفع آمن». */
  title: string;
  /** سطر ثانٍ — نصّ البند في band وشريحة الحالة في smart. */
  description?: string;
  /** أيقونة زخرفية (مرّرها بـaria-hidden). */
  icon?: ReactNode;
  /** smart فقط: لون النقطة. */
  tone?: 'primary' | 'bright' | 'gold';
  /** smart فقط: الحلقة النابضة — لحالة حيّة فعلًا لا زينةً. */
  live?: boolean;
}>;
/** يستعمل زوج الرموز الداكن (للوضع فوق كروم --ink). */
dark?: boolean;
compact?: boolean;

dtsPropsFor.ToastViewport:
/** يُفرَض TOAST_LIMIT = 2 بنيويًّا: الأحدثان يبقيان. */
toasts: ReadonlyArray<{ id: string; tone: 'status' | 'error'; message: string }>;
/** بدونها لا يُصيَّر زرّ الإغلاق — لا زرّ بلا فعل. */
onDismiss?: (id: string) => void;
/** مهلة الإخفاء التلقائي لكل إشعار؛ 0 يوقفها. */
durationMs?: number;
children?: ReactNode;
